    <div className="docsSteps">{groups.map(g=><section className="docsStep" id={"doc-"+g.id} key={g.id}><div className="docsStepNo">{g.id}</div><div><div className="docsStepTitle"><h3>{g.title}</h3><span>ANIFUZE</span></div><div className="docsTopicGrid">{g.items.map(([t,p])=><div className="docsTopic" key={t}><h4>{t}</h4><p>{p}</p></div>)}</div></div></section>)}</div>
