 const openSupport=async(id)=>{try{setSelectedSupport(id);setSupportMessages(await api("/admin/support/cases/"+id+"/messages"));const socket=io((import.meta.env.VITE_API_URL||"https://animefusion.onrender.com"),{auth:{token:getAuthToken()},transports:["websocket"]});socket.on("connect",()=>socket.emit("case:join",id));socket.on("message:new",m=>{setSupportMessages(v=>v.some(x=>x.id===m.id)?v:[...v,m]);setSupportCases(v=>v.map(c=>c.id===id?{...c,message_count:Number(c.message_count||0)+1,updated_at:m.created_at}:c))});setSupportSocket(socket)}catch(e){alert(e.message||"Unable to open support case")}};
 const updateSupport=async(id,patch)=>{try{const q=await api("/admin/support/cases/"+id,{method:"PATCH",body:JSON.stringify(patch)});setSupportCases(v=>v.map(c=>c.id===id?{...c,...q}:c))}catch(e){alert(e.message||"Unable to update case")}};
