 {tab==="products"&&<section className="adminModule"><div className="adminModuleHead"><div><span>COMMERCE</span><h2>Products</h2><p>Manage the catalog used by AniFuze commerce.</p></div></div><form className="adminProductForm" onSubmit={createProduct}><input required placeholder="slug" value={productForm.slug} onChange={e=>setProductForm({...productForm,slug:e.target.value})}/><input required placeholder="Product name" value={productForm.name} onChange={e=>setProductForm({...productForm,name:e.target.value})}/><input required type="number" min="0" placeholder="Price cents" value={productForm.priceCents} onChange={e=>setProductForm({...productForm,priceCents:e.target.value})}/><select value={productForm.productType} onChange={e=>setProductForm({...productForm,productType:e.target.value})}><option value="platform">Platform</option><option value="template">Template</option><option value="service">Service</option></select><button className="adminApprove">Create product</button></form>{loading?<div className="adminEmpty">Loading products…</div>:<div className="adminTable">{products.map(p=><div className="adminTableRow" key={p.id}><div><b>{p.name}</b><span>{p.slug}</span></div><span>{p.product_type}</span><b>{money(p.price_cents,p.currency)}</b><span>{p.active?"Active":"Disabled"}</span><button onClick={async()=>{try{const q=await api("/admin/products/"+p.id,{method:"PATCH",body:JSON.stringify({active:!p.active})});setProducts(x=>x.map(v=>v.id===q.id?q:v))}catch(e){alert(e.message)}}}>{p.active?"Disable":"Enable"}</button></div>)}</div>}</section>}
